note.ddx:
{
  "step1_summary": "• Chief complaint: Bilateral (predominantly right) knee pain with clicking during and after running/work-outs.\n• Symptom details: Began ~2 weeks ago after increasing run distance for marathon training; pain starts ≈20 min / ~3 mi into run, sometimes forces her to stop; occasional clicking during leg-extension/ab work; once noticed mild swelling that resolved with ice; single episode of right-toe tingling post-run; no locking, giving-way, or constant pain; full range of motion; no baseline swelling, redness, fever.\n• Past medical history: Hyperopia (LASIK), prior significant UTI/possible renal colic; remote right knee contusion from ice-hockey fall months ago; otherwise healthy.\n• Medications/allergies: Ibuprofen 400 mg PRN, Aleve (naproxen) PRN, vitamin D, melatonin, occasional Xanax; smokes marijuana joints; no allergies reported.\n• Family/social history: Active—ice hockey, regular gym, currently marathon training; lives in London; no smoking/tobacco or alcohol history stated; occasional marijuana use.\n• Vital signs/exam findings (video only): No current swelling, erythema, or warmth; right knee pain localized “middle then slightly to the right”; full flexion/extension; clicking with gym leg movements; able to walk, climb stairs without pain; no calf tenderness, colour change, or temperature change in legs; mild sock indentation oedema after prolonged standing.\n• Labs/imaging: None performed yet.",
  "step2_vindicate": {
    "V": [
      "Deep venous thrombosis: Could give unilateral calf/knee discomfort and toe tingling, but absence of persistent swelling, calf pain, or risk factors makes it unlikely."
    ],
    "I": [
      "Septic arthritis / acute inflammatory arthritis: Would present with swollen, hot, painful joint and systemic features—currently not present but kept in mind if swelling/fever develop.",
      "Prepatellar bursitis: Overuse or kneeling can inflame bursa and cause anterior knee pain/swelling; transient swelling described."
    ],
    "N": [
      "Bone/soft-tissue neoplasm (e.g., osteoid osteoma, synovial sarcoma): Chronic, progressive pain usually unrelated to activity; no red-flag features but theoretically possible."
    ],
    "D": [
      "Patellofemoral pain syndrome (chondromalacia patella): Classic overuse injury in runners causing anterior knee pain, clicking, aggravated by running, squatting, stairs.",
      "Early degenerative meniscal tear: Can cause pain and clicking; prior hockey fall could be inciting trauma.",
      "Patellar tendinopathy (jumper’s knee): Overuse of extensor mechanism with pain worsened by running and leg extension."
    ],
    "I2": [
      "NSAID-induced gastritis/ulcer (iatrogenic) – relevant to treatment plan but not cause of knee pain."
    ],
    "C": [
      "Congenital patellar maltracking/ hypermobility: Could predispose to patellofemoral pain in active patient."
    ],
    "A": [
      "Early rheumatoid arthritis or other autoimmune arthropathy: Less likely given mono-articular, activity-related pain and lack of stiffness, swelling."
    ],
    "T": [
      "Anterior cruciate ligament or medial collateral ligament sprain/tear: Patient worried about ACL; remote fall and current running could strain ligaments, but no instability or giving-way reported.",
      "Iliotibial band syndrome: Overuse friction causing lateral knee pain after running."
    ],
    "E": [
      "Vitamin D deficiency–related bone/joint pain: She supplements vitamin D; presentation activity-linked."
    ]
  },
  "step3_ranked_ddx": [
    {
      "diagnosis": "Patellofemoral pain syndrome (runner’s knee / chondromalacia patella)",
      "likelihood": "High",
      "explanation": "Most common cause of anterior knee pain in young runners; provoked by increased mileage, characterized by pain after prolonged running, clicking with flexion/extension, and usually normal exam aside from retropatellar tenderness (not tested here).",
      "supporting_evidence": [
        "Onset after increasing run distance for marathon training",
        "Pain starts ~20 min into run and with leg-extension exercises",
        "Clicking during flexion/extension",
        "No locking, instability, or consistent swelling",
        "Full range of motion"
      ],
      "opposing_evidence": [
        "Pain described as ‘middle then right side’ rather than classic anterior location",
        "Single prior swelling episode (PFPS usually non-swollen)"
      ]
    },
    {
      "diagnosis": "Patellar tendinopathy (jumper’s knee)",
      "likelihood": "Medium",
      "explanation": "Overuse of the extensor mechanism from running and gym work can inflame patellar tendon causing pain with activity and clicking sensations.",
      "supporting_evidence": [
        "Activity-related pain, worse with running and leg extension exercises",
        "Improvement with rest/ice",
        "No instability"
      ],
      "opposing_evidence": [
        "Pain location not clearly inferior to patella/tendon described",
        "Clicking less typical of tendinopathy"
      ]
    },
    {
      "diagnosis": "Meniscal tear (degenerative or traumatic)",
      "likelihood": "Medium",
      "explanation": "Prior knee trauma (hockey fall) plus new repetitive running could aggravate a meniscal tear, producing pain and mechanical symptoms like clicking.",
      "supporting_evidence": [
        "History of knee trauma months ago",
        "Clicking in knee",
        "Pain that worsens during longer runs"
      ],
      "opposing_evidence": [
        "No locking, giving-way, or inability to fully extend/flex",
        "Currently no effusion; meniscal tears often present with persistent swelling"
      ]
    },
    {
      "diagnosis": "Iliotibial band syndrome",
      "likelihood": "Low-Medium",
      "explanation": "Common runner overuse injury causing lateral knee pain after certain mileage.",
      "supporting_evidence": [
        "Pain may ‘move to the right side of knee’",
        "Triggered after ~3 miles of running"
      ],
      "opposing_evidence": [
        "No tenderness over lateral femoral epicondyle reported",
        "Clicking less characteristic"
      ]
    },
    {
      "diagnosis": "Ligamentous injury (ACL/MCL sprain)",
      "likelihood": "Low",
      "explanation": "Could stem from prior hockey fall but typically causes instability or acute swelling, which she denies.",
      "supporting_evidence": [
        "Patient concern due to reading about ACL; history of fall"
      ],
      "opposing_evidence": [
        "No giving-way, instability, or acute swelling",
        "Able to run and perform activities until pain starts"
      ]
    }
  ]
}
